module.exports = {"DelayLive.html":{"contentType":"text/html; charset=utf-8","binary":false,"content":"<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\" />\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  <title>Delay Live Player</title>\r\n  <style>\r\n    body {\r\n      margin: 0;\r\n      overflow: hidden;\r\n      /* Hide scrollbars */\r\n      background-color: black;\r\n    }\r\n\r\n    #player {\r\n      position: absolute;\r\n      top: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 100%;\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n  <div id=\"player\"></div>\r\n\r\n  <script>\r\n    let player;\r\n    const PLAYER_KEY = \"delayLivePlayerCommand\"; // Unique key for this player in localStorage\r\n    const EVENT_REPORT_KEY = \"delayLivePlayerEvent\"; // Key to report events back to controller\r\n    let durationTimer; // To manage the end time of playback\r\n    let timeUpdateInterval = null; // 24/7 Reliability: Track interval for cleanup\r\n    // Store current start/end seconds in variables (not from localStorage on each play)\r\n    let currentStartSeconds = 0;\r\n    let currentEndSeconds = null;\r\n    let isLoadingVideo = false; // Flag to prevent videoEnded during loading\r\n    let lastLoadedVideoId = null; // Track last loaded video to prevent duplicate ended events\r\n\r\n    // Function to load the YouTube IFrame API asynchronously\r\n    function loadYouTubeAPI() {\r\n      const tag = document.createElement(\"script\");\r\n      tag.src = \"https://www.youtube.com/iframe_api\"; // Corrected YouTube API URL\r\n      const firstScriptTag = document.getElementsByTagName(\"script\")[0];\r\n      firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);\r\n    }\r\n\r\n    // This function is called by the YouTube API when it's ready\r\n    function onYouTubeIframeAPIReady() {\r\n      console.log(\"YouTube IFrame API is ready for DelayLivePlayer.\");\r\n      // Player will be created when a video is loaded via localStorage command\r\n    }\r\n\r\n    function createPlayer(videoId, startSeconds = 0, endSeconds = null) {\r\n      // Store the times in variables for later use\r\n      currentStartSeconds = startSeconds;\r\n      currentEndSeconds = endSeconds;\r\n\r\n      if (player) {\r\n        player.destroy();\r\n      }\r\n      player = new YT.Player(\"player\", {\r\n        videoId: videoId,\r\n        playerVars: {\r\n          autoplay: 1, // Autoplay the video\r\n          controls: 0, // Hide video controls\r\n          disablekb: 1, // Disable keyboard controls\r\n          fs: 0, // Disable fullscreen button\r\n          iv_load_policy: 3, // Hide video annotations by default\r\n          modestbranding: 1, // Hide YouTube logo\r\n          rel: 0, // Do not show related videos\r\n          showinfo: 0, // Hide video title and uploader info\r\n          start: startSeconds || 0, // Start time in seconds\r\n          end: endSeconds || undefined, // End time in seconds, or undefined if not set\r\n        },\r\n        events: {\r\n          onReady: onPlayerReady,\r\n          onStateChange: onPlayerStateChange,\r\n          onError: onPlayerError,\r\n        },\r\n      });\r\n    }\r\n\r\n    function onPlayerReady(event) {\r\n      console.log(\"DelayLivePlayer is ready!\");\r\n      event.target.playVideo(); // Autoplay on ready\r\n      // Use stored times instead of re-reading from localStorage\r\n      startDurationTimer(event.target, currentStartSeconds, currentEndSeconds);\r\n    }\r\n\r\n    function onPlayerStateChange(event) {\r\n      let state;\r\n      switch (event.data) {\r\n        case YT.PlayerState.ENDED:\r\n          state = \"ended\";\r\n          clearDurationTimer();\r\n          // Only report videoEnded if not in loading state\r\n          if (!isLoadingVideo) {\r\n            // Report video ended event to the controller\r\n            reportEvent(\"videoEnded\", {\r\n              videoId: player.getVideoData().video_id,\r\n            });\r\n            // Explicitly pause the video here, instead of looping, so the controller can take over\r\n            if (player) {\r\n              player.pauseVideo();\r\n              console.log(\r\n                \"DelayLivePlayer: Video ended, paused and reported to controller.\"\r\n              );\r\n            }\r\n          } else {\r\n            console.log(\"DelayLivePlayer: Ignoring ENDED state during video loading.\");\r\n          }\r\n          break;\r\n        case YT.PlayerState.PLAYING:\r\n          state = \"playing\";\r\n          isLoadingVideo = false; // Video started playing, loading complete\r\n          // Use stored times instead of re-reading from localStorage\r\n          startDurationTimer(event.target, currentStartSeconds, currentEndSeconds);\r\n          break;\r\n        case YT.PlayerState.PAUSED:\r\n          state = \"paused\";\r\n          clearDurationTimer();\r\n          break;\r\n        case YT.PlayerState.BUFFERING:\r\n          state = \"buffering\";\r\n          break;\r\n        case YT.PlayerState.CUED:\r\n          state = \"cued\";\r\n          break;\r\n        case YT.PlayerState.UNSTARTED:\r\n          state = \"unstarted\";\r\n          break;\r\n        default:\r\n          state = \"unknown\";\r\n      }\r\n      console.log(\"DelayLivePlayer state changed:\", state);\r\n    }\r\n\r\n    function onPlayerError(event) {\r\n      console.error(\"DelayLivePlayer error:\", event.data);\r\n      clearDurationTimer();\r\n      reportEvent(\"videoError\", {\r\n        error: event.data,\r\n        videoId: player ? player.getVideoData().video_id : \"N/A\",\r\n      });\r\n    }\r\n\r\n    // Modified to receive start and end seconds directly, so it uses the *current* effective range\r\n    function startDurationTimer(playerInstance, startSec, endSec) {\r\n      clearDurationTimer(); // Clear any existing timer\r\n\r\n      if (endSec !== null && endSec !== undefined && endSec > 0) {\r\n        durationTimer = setInterval(() => {\r\n          const currentTime = playerInstance.getCurrentTime();\r\n          // If current time exceeds endSeconds, report to controller and pause\r\n          if (currentTime >= endSec) {\r\n            console.log(\r\n              `DelayLivePlayer: Reached end time ${endSec}. Reporting 'videoEnded' to controller.`\r\n            );\r\n            reportEvent(\"videoEnded\", {\r\n              videoId: playerInstance.getVideoData().video_id,\r\n            });\r\n            playerInstance.pauseVideo(); // Pause the video\r\n            clearDurationTimer(); // Stop checking once ended\r\n          }\r\n        }, 500); // Check every 500ms\r\n      }\r\n    }\r\n\r\n    function clearDurationTimer() {\r\n      if (durationTimer) {\r\n        clearInterval(durationTimer);\r\n        durationTimer = null;\r\n      }\r\n    }\r\n\r\n    // Function to report events back to the main controller\r\n    function reportEvent(eventName, data = {}) {\r\n      const eventData = {\r\n        playerType: \"delay\",\r\n        event: eventName,\r\n        timestamp: Date.now(),\r\n        ...data,\r\n      };\r\n      localStorage.setItem(EVENT_REPORT_KEY, JSON.stringify(eventData));\r\n      // Clear the item after a short delay to ensure the 'storage' event fires cleanly\r\n      setTimeout(() => {\r\n        localStorage.removeItem(EVENT_REPORT_KEY);\r\n      }, 100);\r\n    }\r\n\r\n    // Event listener for changes in localStorage\r\n    window.addEventListener(\"storage\", (event) => {\r\n      if (event.key === PLAYER_KEY && event.newValue) {\r\n        try {\r\n          const commandData = JSON.parse(event.newValue);\r\n          if (commandData && commandData.command) {\r\n            console.log(\"DelayLivePlayer received command:\", commandData);\r\n            switch (commandData.command) {\r\n              case \"loadVideo\":\r\n                // Safety check: ensure YT API is ready\r\n                if (typeof YT === \"undefined\" || typeof YT.Player === \"undefined\") {\r\n                  console.error(\"DelayLivePlayer: YouTube IFrame API (YT.Player) is not yet ready. Cannot create player.\");\r\n                  return;\r\n                }\r\n\r\n                const videoId = commandData.videoId;\r\n                const startSeconds =\r\n                  commandData.startSeconds !== undefined\r\n                    ? parseInt(commandData.startSeconds)\r\n                    : 0;\r\n                const endSeconds =\r\n                  commandData.endSeconds !== undefined && commandData.endSeconds > 0\r\n                    ? parseInt(commandData.endSeconds)\r\n                    : null;\r\n\r\n                if (videoId) {\r\n                  // Store times in variables\r\n                  currentStartSeconds = startSeconds;\r\n                  currentEndSeconds = endSeconds;\r\n                  isLoadingVideo = true; // Set loading flag\r\n                  lastLoadedVideoId = videoId;\r\n\r\n                  if (player && typeof player.loadVideoById === 'function') {\r\n                    // Reuse existing player for efficiency\r\n                    console.log(`DelayLivePlayer: Loading video ${videoId} via loadVideoById from ${startSeconds} to ${endSeconds}`);\r\n                    player.loadVideoById({\r\n                      videoId: videoId,\r\n                      startSeconds: startSeconds,\r\n                      endSeconds: endSeconds || undefined\r\n                    });\r\n                    // Start duration timer for custom end handling\r\n                    startDurationTimer(player, startSeconds, endSeconds);\r\n                  } else {\r\n                    // Create new player\r\n                    createPlayer(videoId, startSeconds, endSeconds);\r\n                    console.log(`DelayLivePlayer: Created new player for video ${videoId} from ${startSeconds} to ${endSeconds}`);\r\n                  }\r\n                } else {\r\n                  console.warn(\"DelayLivePlayer: No videoId provided for loadVideo command.\");\r\n                }\r\n                break;\r\n              case \"play\":\r\n                if (player) {\r\n                  player.playVideo();\r\n                  // Retrieve last loaded start/end times to re-establish timer\r\n                  const lastLoadCommand = JSON.parse(\r\n                    localStorage.getItem(PLAYER_KEY) || \"{}\"\r\n                  );\r\n                  const lastStartSec =\r\n                    lastLoadCommand.startSeconds !== undefined\r\n                      ? parseInt(lastLoadCommand.startSeconds)\r\n                      : 0;\r\n                  const lastEndSec =\r\n                    lastLoadCommand.endSeconds !== undefined\r\n                      ? parseInt(lastLoadCommand.endSeconds)\r\n                      : null;\r\n                  startDurationTimer(player, lastStartSec, lastEndSec);\r\n                }\r\n                break;\r\n              case \"pause\":\r\n                if (player) {\r\n                  player.pauseVideo();\r\n                  clearDurationTimer(); // Stop timer on pause\r\n                }\r\n                break;\r\n              case \"stop\":\r\n                if (player) {\r\n                  player.stopVideo();\r\n                  clearDurationTimer(); // Stop timer on stop\r\n                  player.destroy(); // Destroy player to clear current video\r\n                  player = null;\r\n                }\r\n                break;\r\n              case \"mute\":\r\n                if (player) {\r\n                  player.mute();\r\n                }\r\n                break;\r\n              case \"unmute\":\r\n                if (player) {\r\n                  player.unMute();\r\n                }\r\n                break;\r\n              case \"destroy\":\r\n                // 24/7 Reliability: Clear intervals before destroy\r\n                if (timeUpdateInterval) {\r\n                  clearInterval(timeUpdateInterval);\r\n                  timeUpdateInterval = null;\r\n                }\r\n                if (player) {\r\n                  player.destroy();\r\n                  player = null;\r\n                }\r\n                clearDurationTimer(); // Clear timer if player is destroyed\r\n                break;\r\n            }\r\n          }\r\n        } catch (e) {\r\n          console.error(\r\n            \"Error parsing localStorage command for DelayLivePlayer:\",\r\n            e\r\n          );\r\n        }\r\n      }\r\n    });\r\n    // 24/7 Reliability: Store interval ID for cleanup\r\n    timeUpdateInterval = setInterval(() => {\r\n      // FIX 3: Add a guard clause to ensure the player object exists and is ready\r\n      if (!player || typeof player.getPlayerState !== \"function\") {\r\n        return;\r\n      }\r\n      // Read duration fresh every tick — caching it once made every later\r\n      // video inherit the first video's duration (and remaining time went\r\n      // negative, which the controller renders as a blank).\r\n      const duration = player.getDuration();\r\n      const currentTime = player.getCurrentTime();\r\n      // getDuration() returns 0 until the video's metadata is loaded — skip until then\r\n      if (player.getPlayerState() === YT.PlayerState.PLAYING && duration > 0) {\r\n        reportEvent(\"timeUpdate\", {\r\n          currentTime,\r\n          duration,\r\n          remainingTime: Math.max(0, duration - currentTime)\r\n        });\r\n      }\r\n    }, 1000);\r\n\r\n    // Load the YouTube API when the page loads\r\n    loadYouTubeAPI();\r\n  </script>\r\n</body>\r\n\r\n</html>"},"firebase-messaging-sw.js":{"contentType":"application/javascript; charset=utf-8","binary":false,"content":"// Live TV Controller — Push Notification Service Worker\n// Plain Web Push handler — no external CDN scripts required.\n// This is simpler and more reliable than importing Firebase SDK scripts\n// because it works even when gstatic.com CDN is slow or unreachable.\n\n// Take over immediately when the SW is updated (no waiting for tabs to close)\nself.addEventListener('install', (event) => {\n  self.skipWaiting();\n});\n\n// Claim all open clients so this SW controls them right away\nself.addEventListener('activate', (event) => {\n  event.waitUntil(clients.claim());\n});\n\n// Pass every fetch straight to the network — this SW is push-only, no caching.\n// Without this passthrough, the SW scope (/) would intercept page loads and\n// serve stale cached assets on soft reload (F5).\nself.addEventListener('fetch', (event) => {\n  return;\n});\n\n// Push event — called by Chrome when FCM delivers a push to this subscription\nself.addEventListener('push', (event) => {\n  if (!event.data) return;\n\n  let payload;\n  try {\n    payload = event.data.json();\n  } catch {\n    return; // non-JSON push — ignore\n  }\n\n  // FCM HTTP v1 merges notification + webpush.notification into payload.notification.\n  // Our server also sets data.tag so same-event notifications collapse (replace each other).\n  const notification = payload.notification || {};\n  const data = payload.data || {};\n\n  const title = notification.title || 'Live TV Controller';\n  const tag   = data.tag || notification.tag || 'livetv';\n\n  event.waitUntil(\n    self.registration.showNotification(title, {\n      body:     notification.body  || '',\n      icon:     notification.icon  || '/icon-192.png',\n      tag,\n      badge:    '/icon-192.png',\n      renotify: true,\n    })\n  );\n});\n\n// Notification click — bring existing tab into focus or open a new one\nself.addEventListener('notificationclick', (event) => {\n  event.notification.close();\n  event.waitUntil(\n    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {\n      for (const client of clientList) {\n        if (client.url.includes(self.location.origin) && 'focus' in client) {\n          return client.focus();\n        }\n      }\n      if (clients.openWindow) return clients.openWindow('/');\n    })\n  );\n});\n"},"icon-192.png":{"contentType":"image/png","binary":true,"content":""},"icon-512.png":{"contentType":"image/png","binary":true,"content":""},"LivePlayer.html":{"contentType":"text/html; charset=utf-8","binary":false,"content":"<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\" />\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  <title>Live Player</title>\r\n  <style>\r\n    body {\r\n      margin: 0;\r\n      overflow: hidden;\r\n      /* Hide scrollbars */\r\n      background-color: black;\r\n    }\r\n\r\n    #player {\r\n      position: absolute;\r\n      top: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 100%;\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n  <div id=\"player\"></div>\r\n\r\n  <script>\r\n    let player;\r\n    const PLAYER_KEY = \"livePlayerCommand\"; // Unique key for this player in localStorage\r\n    const LIVE_PLAYER_EVENT_KEY = 'livePlayerEvent';\r\n    let isLoadingVideo = false; // Flag to prevent videoEnded during loading\r\n    let timeUpdateInterval = null; // 24/7 Reliability: Track interval for cleanup\r\n\r\n    function loadYouTubeAPI() {\r\n      const tag = document.createElement(\"script\");\r\n      tag.src = \"https://www.youtube.com/iframe_api\"; // Corrected YouTube API URL\r\n      const firstScriptTag = document.getElementsByTagName(\"script\")[0];\r\n      firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);\r\n    }\r\n\r\n    function onYouTubeIframeAPIReady() {\r\n      console.log(\"YouTube IFrame API is ready for LivePlayer.\");\r\n    }\r\n\r\n    // Event listener for changes in localStorage\r\n    window.addEventListener(\"storage\", (event) => {\r\n      if (event.key === PLAYER_KEY && event.newValue) {\r\n        try {\r\n          const data = JSON.parse(event.newValue);\r\n          console.log(\r\n            \"Command received in LivePlayer via localStorage:\",\r\n            data\r\n          );\r\n\r\n          if (data.command === \"loadVideo\" && data.videoId) {\r\n            isLoadingVideo = true; // Set loading flag\r\n            if (player) {\r\n              player.loadVideoById({\r\n                videoId: data.videoId,\r\n                playerVars: {\r\n                  autoplay: 1,\r\n                  controls: 0,\r\n                  modestbranding: 1,\r\n                  showinfo: 0,\r\n                  rel: 0,\r\n                  fs: 1,\r\n                  iv_load_policy: 3,\r\n                },\r\n              });\r\n            } else {\r\n              // Safety check: ensure YT API is ready\r\n              if (typeof YT === \"undefined\" || typeof YT.Player === \"undefined\") {\r\n                console.error(\"LivePlayer: YouTube IFrame API (YT.Player) is not yet ready. Cannot create player.\");\r\n                return;\r\n              }\r\n              player = new YT.Player(\"player\", {\r\n                videoId: data.videoId,\r\n                playerVars: {\r\n                  autoplay: 1,\r\n                  controls: 0,\r\n                  modestbranding: 1,\r\n                  showinfo: 0,\r\n                  rel: 0,\r\n                  fs: 1,\r\n                  iv_load_policy: 3,\r\n                },\r\n                events: {\r\n                  onReady: onPlayerReady,\r\n                  onStateChange: onPlayerStateChange,\r\n                  onError: onPlayerError\r\n                },\r\n              });\r\n            }\r\n          } else if (player) {\r\n            switch (data.command) {\r\n              case \"play\":\r\n                player.playVideo();\r\n                break;\r\n              case \"pause\":\r\n                player.pauseVideo();\r\n                break;\r\n              case \"stop\":\r\n                player.stopVideo();\r\n                break;\r\n              case \"mute\":\r\n                player.mute();\r\n                break;\r\n              case \"unmute\":\r\n                player.unMute();\r\n                break;\r\n              case \"setVolume\":\r\n                if (typeof data.volume === \"number\") {\r\n                  player.setVolume(data.volume);\r\n                }\r\n                break;\r\n              case \"seekTo\":\r\n                if (typeof data.seconds === \"number\") {\r\n                  player.seekTo(data.seconds, true);\r\n                }\r\n                break;\r\n              case \"destroy\":\r\n                // 24/7 Reliability: Clear interval before destroy\r\n                if (timeUpdateInterval) {\r\n                  clearInterval(timeUpdateInterval);\r\n                  timeUpdateInterval = null;\r\n                }\r\n                player.destroy();\r\n                player = null;\r\n                break;\r\n            }\r\n          }\r\n        } catch (e) {\r\n          console.error(\r\n            \"Error parsing localStorage command for LivePlayer:\",\r\n            e\r\n          );\r\n        }\r\n      }\r\n    });\r\n\r\n    function onPlayerReady(event) {\r\n      console.log(\"LivePlayer is ready!\");\r\n      event.target.playVideo();\r\n      // event.target.mute(); // Commented out to allow unmuted playback on load\r\n    }\r\n\r\n    function onPlayerStateChange(event) {\r\n      let state;\r\n      switch (event.data) {\r\n        case YT.PlayerState.ENDED:\r\n          state = \"ended\";\r\n          // Only report videoEnded if not in loading state\r\n          if (!isLoadingVideo) {\r\n            localStorage.setItem(\r\n              LIVE_PLAYER_EVENT_KEY,\r\n              JSON.stringify({ playerType: \"live\", event: \"videoEnded\" })\r\n            );\r\n            setTimeout(() => {\r\n              localStorage.removeItem(LIVE_PLAYER_EVENT_KEY);\r\n            }, 100);\r\n          } else {\r\n            console.log(\"LivePlayer: Ignoring ENDED state during video loading.\");\r\n          }\r\n          break;\r\n        case YT.PlayerState.PLAYING:\r\n          state = \"playing\";\r\n          isLoadingVideo = false; // Video started playing, loading complete\r\n          break;\r\n        case YT.PlayerState.PAUSED:\r\n          state = \"paused\";\r\n          break;\r\n        case YT.PlayerState.BUFFERING:\r\n          state = \"buffering\";\r\n          break;\r\n        case YT.PlayerState.CUED:\r\n          state = \"cued\";\r\n          break;\r\n        case YT.PlayerState.UNSTARTED:\r\n          state = \"unstarted\";\r\n          break;\r\n        default:\r\n          state = \"unknown\";\r\n      }\r\n      console.log(\"LivePlayer state changed:\", state);\r\n    }\r\n\r\n    function onPlayerError(event) {\r\n      let errorMessage = \"Unknown error\";\r\n      switch (event.data) {\r\n        case 2:\r\n          errorMessage = \"Invalid video ID or video not found.\";\r\n          break;\r\n        case 100:\r\n          errorMessage = \"Video not found.\";\r\n          break;\r\n        case 101:\r\n        case 150:\r\n          errorMessage =\r\n            \"Video cannot be played in an embedded player (e.g., private video, restricted playback).\";\r\n          break;\r\n      }\r\n      console.error(\r\n        \"LivePlayer: Error:\",\r\n        errorMessage,\r\n        \"Error code:\",\r\n        event.data\r\n      );\r\n      // Report videoError so controller can switch to another player\r\n      localStorage.setItem(\r\n        LIVE_PLAYER_EVENT_KEY,\r\n        JSON.stringify({ playerType: \"live\", event: \"videoError\", errorCode: event.data })\r\n      );\r\n      setTimeout(() => {\r\n        localStorage.removeItem(LIVE_PLAYER_EVENT_KEY);\r\n      }, 100);\r\n    }\r\n\r\n    // Function to report events back to the main controller\r\n    function reportEvent(eventName, data = {}) {\r\n      const eventData = {\r\n        playerType: \"live\",\r\n        event: eventName,\r\n        timestamp: Date.now(),\r\n        ...data,\r\n      };\r\n      localStorage.setItem(LIVE_PLAYER_EVENT_KEY, JSON.stringify(eventData));\r\n      // Clear the item after a short delay to ensure the 'storage' event fires cleanly\r\n      setTimeout(() => {\r\n        localStorage.removeItem(LIVE_PLAYER_EVENT_KEY);\r\n      }, 100);\r\n    }\r\n    // 24/7 Reliability: Store interval ID for cleanup\r\n    timeUpdateInterval = setInterval(() => {\r\n      // FIX 3: Add a guard clause to ensure the player object exists and is ready\r\n      if (!player || typeof player.getPlayerState !== \"function\") {\r\n        return;\r\n      }\r\n      // Read duration fresh every tick — caching it once made every later\r\n      // video inherit the first video's duration (and remaining time went\r\n      // negative, which the controller renders as a blank).\r\n      const duration = player.getDuration();\r\n      const currentTime = player.getCurrentTime();\r\n      // getDuration() returns 0 until the video's metadata is loaded — skip until then\r\n      if (player.getPlayerState() === YT.PlayerState.PLAYING && duration > 0) {\r\n        reportEvent(\"timeUpdate\", {\r\n          currentTime,\r\n          duration,\r\n          remainingTime: Math.max(0, duration - currentTime)\r\n        });\r\n      }\r\n    }, 1000);\r\n    loadYouTubeAPI();\r\n  </script>\r\n</body>\r\n\r\n</html>"},"LocalPCPlayer.html":{"contentType":"text/html; charset=utf-8","binary":false,"content":"<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\" />\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  <title>Local PC Player</title>\r\n  <style>\r\n    body {\r\n      margin: 0;\r\n      overflow: hidden;\r\n      background-color: black;\r\n    }\r\n\r\n    #localVideoPlayer {\r\n      position: absolute;\r\n      top: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: contain;\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n  <!-- NOTE: No autoplay attribute — play is triggered exclusively by JS (playVideoWithSound) -->\r\n  <video id=\"localVideoPlayer\" playsinline></video>\r\n\r\n  <script>\r\n    const videoPlayer = document.getElementById(\"localVideoPlayer\");\r\n    const PLAYER_KEY_LOCAL = \"localPCPlayerCommand\";\r\n    const EVENT_REPORT_KEY_LOCAL = \"localPCPlayerEvent\";\r\n\r\n    // Time tracking variables\r\n    let startTime = 0;\r\n    let endTime = null;\r\n    let timeCheckInterval = null;\r\n    let isPausedByCommand = false; // Track if pause was requested by controller\r\n    let userRequestedMute = false; // Track explicit mute command — prevents late-unmute from overriding it\r\n    let needsPlay = false;         // Set before load(); play triggered from loadedmetadata after seek\r\n    let srcCleared = false;        // Set when stop intentionally empties src — suppresses spurious error event\r\n\r\n    function reportEvent(eventName, data = {}) {\r\n      const eventData = {\r\n        playerType: \"local\",\r\n        event: eventName,\r\n        timestamp: Date.now(),\r\n        ...data,\r\n      };\r\n      console.log(\"LocalPCPlayer: Reporting event:\", eventData);\r\n      localStorage.setItem(EVENT_REPORT_KEY_LOCAL, JSON.stringify(eventData));\r\n      setTimeout(() => {\r\n        localStorage.removeItem(EVENT_REPORT_KEY_LOCAL);\r\n      }, 100);\r\n    }\r\n\r\n    // Returns true if dur is a usable duration value\r\n    function isValidDuration(dur) {\r\n      return typeof dur === 'number' && isFinite(dur) && !isNaN(dur) && dur > 0;\r\n    }\r\n\r\n    // Emit a timeUpdate event with the current playback position and duration.\r\n    // ctOverride lets callers supply a known currentTime (e.g. right after a seek\r\n    // where videoPlayer.currentTime may not yet reflect the new position).\r\n    function emitTimeUpdate(ctOverride) {\r\n      const dur = videoPlayer.duration;\r\n      if (!isValidDuration(dur)) return;\r\n      const ct = (ctOverride !== undefined) ? ctOverride : videoPlayer.currentTime;\r\n      const effectiveEnd = endTime !== null ? endTime : dur;\r\n      reportEvent(\"timeUpdate\", {\r\n        currentTime: ct,\r\n        duration: dur,\r\n        remainingTime: Math.max(0, effectiveEnd - ct),\r\n        startTime,\r\n        endTime,\r\n      });\r\n    }\r\n\r\n    function checkAndHandleEndTime() {\r\n      if (endTime !== null && videoPlayer.currentTime >= endTime) {\r\n        videoPlayer.pause();\r\n        clearInterval(timeCheckInterval);\r\n        reportEvent(\"videoEnded\");\r\n      }\r\n    }\r\n\r\n    function startTimeChecking() {\r\n      clearInterval(timeCheckInterval);\r\n      if (endTime !== null) {\r\n        timeCheckInterval = setInterval(checkAndHandleEndTime, 250);\r\n      }\r\n    }\r\n\r\n    function stopTimeChecking() {\r\n      clearInterval(timeCheckInterval);\r\n    }\r\n\r\n    videoPlayer.addEventListener(\"loadedmetadata\", () => {\r\n      console.log(\"LocalPCPlayer: Video metadata loaded:\", {\r\n        duration: videoPlayer.duration,\r\n        startTime: startTime,\r\n        endTime: endTime,\r\n        src: videoPlayer.src\r\n      });\r\n\r\n      // Seek FIRST so play() starts at the correct position\r\n      if (startTime > 0) {\r\n        videoPlayer.currentTime = startTime;\r\n      }\r\n\r\n      reportEvent(\"videoLoaded\", {\r\n        duration: videoPlayer.duration,\r\n        startTime: startTime,\r\n        endTime: endTime,\r\n      });\r\n\r\n      // Immediately notify the UI of the new video's duration so it can reset\r\n      // the display before the first timeUpdate tick arrives.\r\n      if (isValidDuration(videoPlayer.duration)) {\r\n        reportEvent(\"durationUpdate\", {\r\n          duration: videoPlayer.duration,\r\n        });\r\n      }\r\n\r\n      // Immediately push a timeUpdate so the UI shows duration/position before\r\n      // the first timeupdate tick fires. Use startTime as the effective current\r\n      // position because the seek above may not have committed synchronously yet.\r\n      emitTimeUpdate(startTime || 0);\r\n\r\n      // Play after seek is applied — avoids brief play from 0 before jumping to startTime\r\n      if (needsPlay) {\r\n        needsPlay = false;\r\n        playVideoWithSound();\r\n      }\r\n    });\r\n\r\n    videoPlayer.addEventListener(\"play\", () => {\r\n      console.log(\"LocalPCPlayer: Video playing, unmuted:\", !videoPlayer.muted);\r\n      isPausedByCommand = false;\r\n      startTimeChecking();\r\n      emitTimeUpdate();\r\n    });\r\n\r\n    // FIXED: Only report videoEnded on actual natural video end, NOT on pause\r\n    videoPlayer.addEventListener(\"pause\", () => {\r\n      console.log(\"LocalPCPlayer: Video paused, isPausedByCommand:\", isPausedByCommand);\r\n      stopTimeChecking();\r\n      // Push an immediate update so the display freezes at the correct time,\r\n      // not the last 1-second-tick value.\r\n      emitTimeUpdate();\r\n    });\r\n\r\n    videoPlayer.addEventListener(\"timeupdate\", () => {\r\n      emitTimeUpdate();\r\n    });\r\n\r\n    videoPlayer.addEventListener(\"seeked\", () => {\r\n      console.log(\"LocalPCPlayer: Video seeked to:\", videoPlayer.currentTime);\r\n      checkAndHandleEndTime();\r\n      // Emit so the UI updates to the new position instantly after seek.\r\n      emitTimeUpdate();\r\n    });\r\n\r\n    // FIXED: Only report videoEnded here - when video actually finishes\r\n    videoPlayer.addEventListener(\"ended\", () => {\r\n      console.log(\"LocalPCPlayer: Video ended naturally\");\r\n      stopTimeChecking();\r\n      reportEvent(\"videoEnded\");\r\n    });\r\n\r\n    videoPlayer.addEventListener(\"error\", (e) => {\r\n      // Suppress spurious error when stop intentionally clears src\r\n      if (srcCleared) { srcCleared = false; return; }\r\n      let errorMessage = \"Unknown video error.\";\r\n      if (videoPlayer.error) {\r\n        switch (videoPlayer.error.code) {\r\n          case MediaError.MEDIA_ERR_ABORTED:\r\n            errorMessage = \"Video fetch aborted.\";\r\n            break;\r\n          case MediaError.MEDIA_ERR_NETWORK:\r\n            errorMessage = \"Network error during video download.\";\r\n            break;\r\n          case MediaError.MEDIA_ERR_DECODE:\r\n            errorMessage = \"Video decoding error.\";\r\n            break;\r\n          case MediaError.MEDIA_ERR_SRC_NOT_SUPPORTED:\r\n            errorMessage = \"Video source not supported.\";\r\n            break;\r\n        }\r\n      }\r\n      console.error(\"LocalPCPlayer: Video error:\", errorMessage, videoPlayer.src);\r\n      stopTimeChecking();\r\n      reportEvent(\"videoError\", { message: errorMessage });\r\n    });\r\n\r\n    // Play video with proper autoplay handling - tries unmuted first, falls back to muted\r\n    async function playVideoWithSound() {\r\n      try {\r\n        // Try playing unmuted first\r\n        videoPlayer.muted = false;\r\n        await videoPlayer.play();\r\n        console.log(\"LocalPCPlayer: Playing with sound SUCCESS\");\r\n      } catch (e) {\r\n        console.warn(\"LocalPCPlayer: Unmuted play failed, trying muted:\", e.message);\r\n        try {\r\n          // Fallback: play muted (browser autoplay policy)\r\n          videoPlayer.muted = true;\r\n          await videoPlayer.play();\r\n          console.log(\"LocalPCPlayer: Playing muted (autoplay policy)\");\r\n          // Try to unmute after a short delay — but only if user hasn't explicitly muted\r\n          setTimeout(() => {\r\n            if (!userRequestedMute) {\r\n              videoPlayer.muted = false;\r\n              console.log(\"LocalPCPlayer: Attempted late unmute\");\r\n            }\r\n          }, 500);\r\n        } catch (e2) {\r\n          console.error(\"LocalPCPlayer: All play attempts failed:\", e2.message);\r\n        }\r\n      }\r\n    }\r\n\r\n    window.addEventListener(\"storage\", (event) => {\r\n      if (event.key === PLAYER_KEY_LOCAL && event.newValue) {\r\n        try {\r\n          const data = JSON.parse(event.newValue);\r\n          console.log(\"LocalPCPlayer: Received command:\", data);\r\n\r\n          switch (data.command) {\r\n            case \"loadVideo\":\r\n            case \"loadVideoOnly\":\r\n              if (data.videoPath) {\r\n                stopTimeChecking();\r\n                srcCleared = false;    // new real load — errors should be reported normally\r\n                isPausedByCommand = false;\r\n                userRequestedMute = false; // reset explicit-mute flag on new video load\r\n\r\n                startTime = data?.startSeconds || 0;\r\n                endTime = data?.endSeconds || null;\r\n\r\n                console.log(\"LocalPCPlayer: Loading video:\", {\r\n                  path: data.videoPath,\r\n                  startTime: startTime,\r\n                  endTime: endTime,\r\n                  autoPlay: data.command === \"loadVideo\",\r\n                });\r\n\r\n                // loadVideoOnly = pre-load without playing; loadVideo = load and play\r\n                needsPlay = data.command === \"loadVideo\";\r\n                videoPlayer.src = data.videoPath;\r\n                videoPlayer.load();\r\n                // playVideoWithSound() is now called from the loadedmetadata handler\r\n                // after currentTime is set — this ensures startTime is respected\r\n              }\r\n              break;\r\n\r\n            case \"play\":\r\n              isPausedByCommand = false;\r\n              playVideoWithSound();\r\n              break;\r\n\r\n            case \"pause\":\r\n              isPausedByCommand = true;\r\n              videoPlayer.pause();\r\n              break;\r\n\r\n            case \"stop\":\r\n              stopTimeChecking();\r\n              needsPlay = false; // cancel any pending play-on-load\r\n              srcCleared = true; // suppress error event from intentional src clear\r\n              isPausedByCommand = true;\r\n              videoPlayer.pause();\r\n              videoPlayer.currentTime = 0;\r\n              videoPlayer.src = \"\";\r\n              startTime = 0;\r\n              endTime = null;\r\n              videoPlayer.load();\r\n              // Reset the display to 00:00 / 00:00 immediately\r\n              reportEvent(\"timeUpdate\", {\r\n                currentTime: 0,\r\n                duration: 0,\r\n                remainingTime: 0,\r\n                startTime: 0,\r\n                endTime: null,\r\n              });\r\n              break;\r\n\r\n            case \"mute\":\r\n              userRequestedMute = true;\r\n              videoPlayer.muted = true;\r\n              console.log(\"LocalPCPlayer: Muted\");\r\n              break;\r\n\r\n            case \"unmute\":\r\n              userRequestedMute = false;\r\n              videoPlayer.muted = false;\r\n              console.log(\"LocalPCPlayer: Unmuted\");\r\n              break;\r\n\r\n            case \"setVolume\":\r\n              if (typeof data.volume === \"number\") {\r\n                videoPlayer.volume = Math.max(0, Math.min(data.volume / 100, 1));\r\n                console.log(\"LocalPCPlayer: Volume set to\", videoPlayer.volume);\r\n              }\r\n              break;\r\n\r\n            case \"seekTo\":\r\n              if (typeof data.seconds === \"number\") {\r\n                const targetTime = Math.max(\r\n                  startTime,\r\n                  Math.min(data.seconds, endTime || videoPlayer.duration)\r\n                );\r\n                videoPlayer.currentTime = targetTime;\r\n                console.log(\"LocalPCPlayer: Seeked to\", targetTime);\r\n              }\r\n              break;\r\n\r\n            case \"getCurrentTime\":\r\n              emitTimeUpdate();\r\n              break;\r\n          }\r\n        } catch (e) {\r\n          console.error(\"LocalPCPlayer: Command parsing error:\", e);\r\n        }\r\n      }\r\n    });\r\n\r\n    // Initial setup - start unmuted\r\n    console.log(\"LocalPCPlayer: Initialized and ready\");\r\n  </script>\r\n</body>\r\n\r\n</html>\r\n"},"LoopPlayer.html":{"contentType":"text/html; charset=utf-8","binary":false,"content":"<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\" />\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  <title>Loop Player</title>\r\n  <style>\r\n    body {\r\n      margin: 0;\r\n      overflow: hidden;\r\n      /* Hide scrollbars */\r\n      background-color: black;\r\n      /* Ensure black background for full screen */\r\n    }\r\n\r\n    #player {\r\n      position: absolute;\r\n      top: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 100%;\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n  <div id=\"player\"></div>\r\n\r\n  <script>\r\n    let player; // Declare player globally\r\n    const PLAYER_KEY = \"loopPlayerCommand\"; // Unique key for this player in localStorage (for incoming commands from Controller.html)\r\n    const PLAYER_EVENT_KEY = \"loopPlayerEvent\"; // Unique key for sending events to Controller.html\r\n    let isLoadingVideo = false; // Flag to prevent videoEnded during loading\r\n    let timeUpdateInterval = null; // 24/7 Reliability: Track interval for cleanup\r\n\r\n    // Function to load the YouTube IFrame API asynchronously\r\n    function loadYouTubeAPI() {\r\n      const tag = document.createElement(\"script\");\r\n      // Corrected YouTube API URL to ensure the player loads correctly\r\n      tag.src = \"https://www.youtube.com/iframe_api\"; // Corrected URL\r\n      const firstScriptTag = document.getElementsByTagName(\"script\")[0];\r\n      firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);\r\n    }\r\n\r\n    // This function is called by the YouTube API when it's ready\r\n    function onYouTubeIframeAPIReady() {\r\n      console.log(\"YouTube IFrame API is ready for LoopPlayer.\");\r\n      // This function is required by the YouTube API.\r\n      // Player creation will happen when a command is received via localStorage.\r\n    }\r\n\r\n    // Event listener for changes in localStorage\r\n    window.addEventListener(\"storage\", (event) => {\r\n      if (event.key === PLAYER_KEY && event.newValue) {\r\n        try {\r\n          const data = JSON.parse(event.newValue);\r\n          console.log(\"LoopPlayer: Command received via localStorage:\", data);\r\n\r\n          if (data.command === \"loadVideo\" && data.videoId) {\r\n            isLoadingVideo = true; // Set loading flag\r\n            if (player) {\r\n              // If player already exists, load new video\r\n              console.log(\r\n                `LoopPlayer: Loading new video ID: ${data.videoId}`\r\n              );\r\n              player.loadVideoById({\r\n                videoId: data.videoId,\r\n                playerVars: {\r\n                  autoplay: 1,\r\n                  controls: 0,\r\n                  modestbranding: 1, // Hide YouTube logo\r\n                  showinfo: 0, // Hide video title and uploader info\r\n                  rel: 0, // Do not show related videos\r\n                  fs: 1, // Enable fullscreen button (though we control it)\r\n                  iv_load_policy: 3, // Do not show video annotations\r\n                },\r\n              });\r\n            } else {\r\n              // Create new player if it doesn't exist\r\n              // Ensure YT.Player is available before trying to create\r\n              if (\r\n                typeof YT !== \"undefined\" &&\r\n                typeof YT.Player !== \"undefined\"\r\n              ) {\r\n                console.log(\r\n                  `LoopPlayer: Creating new player for video ID: ${data.videoId}`\r\n                );\r\n                player = new YT.Player(\"player\", {\r\n                  videoId: data.videoId,\r\n                  playerVars: {\r\n                    autoplay: 1,\r\n                    controls: 0,\r\n                    modestbranding: 1,\r\n                    showinfo: 0,\r\n                    rel: 0,\r\n                    fs: 1,\r\n                    iv_load_policy: 3,\r\n                  },\r\n                  events: {\r\n                    onReady: onPlayerReady,\r\n                    onStateChange: onPlayerStateChange,\r\n                    onError: onPlayerError,\r\n                  },\r\n                });\r\n              } else {\r\n                console.error(\r\n                  \"LoopPlayer: YouTube IFrame API (YT.Player) is not yet ready. Cannot create player.\"\r\n                );\r\n              }\r\n            }\r\n          } else if (player) {\r\n            // Handle other commands if player exists\r\n            switch (data.command) {\r\n              case \"play\":\r\n                console.log(\"LoopPlayer: Playing video.\");\r\n                player.playVideo();\r\n                break;\r\n              case \"pause\":\r\n                console.log(\"LoopPlayer: Pausing video.\");\r\n                player.pauseVideo();\r\n                break;\r\n              case \"stop\":\r\n                console.log(\"LoopPlayer: Stopping and destroying player.\");\r\n                player.stopVideo();\r\n                // 24/7 Reliability: Clear interval before destroy\r\n                if (timeUpdateInterval) {\r\n                  clearInterval(timeUpdateInterval);\r\n                  timeUpdateInterval = null;\r\n                }\r\n                player.destroy(); // Destroy player to clear video\r\n                player = null;\r\n                break;\r\n              case \"mute\":\r\n                console.log(\"LoopPlayer: Muting video.\");\r\n                player.mute();\r\n                break;\r\n              case \"unmute\":\r\n                console.log(\"LoopPlayer: Unmuting video.\");\r\n                player.unMute();\r\n                break;\r\n              case \"setVolume\":\r\n                if (typeof data.volume === \"number\") {\r\n                  console.log(\r\n                    `LoopPlayer: Setting volume to ${data.volume}.`\r\n                  );\r\n                  player.setVolume(data.volume);\r\n                }\r\n                break;\r\n              case \"seekTo\":\r\n                if (typeof data.seconds === \"number\") {\r\n                  console.log(\r\n                    `LoopPlayer: Seeking to ${data.seconds} seconds.`\r\n                  );\r\n                  player.seekTo(data.seconds, true); // true for allowSeekAhead\r\n                }\r\n                break;\r\n              case \"destroy\":\r\n                console.log(\"LoopPlayer: Destroying player.\");\r\n                // 24/7 Reliability: Clear interval before destroy\r\n                if (timeUpdateInterval) {\r\n                  clearInterval(timeUpdateInterval);\r\n                  timeUpdateInterval = null;\r\n                }\r\n                player.destroy();\r\n                player = null;\r\n                break;\r\n            }\r\n          }\r\n        } catch (e) {\r\n          console.error(\"LoopPlayer: Error parsing localStorage command:\", e);\r\n        }\r\n      }\r\n    });\r\n\r\n    function onPlayerReady(event) {\r\n      console.log(\"LoopPlayer: Player is ready!\");\r\n      event.target.playVideo(); // Autoplay on ready\r\n    }\r\n\r\n    function onPlayerStateChange(event) {\r\n      let state;\r\n      switch (event.data) {\r\n        case YT.PlayerState.ENDED:\r\n          state = \"ended\";\r\n          // Only report videoEnded if not in loading state\r\n          if (!isLoadingVideo) {\r\n            // Notify Controller.html that video has ended\r\n            localStorage.setItem(\r\n              PLAYER_EVENT_KEY,\r\n              JSON.stringify({ playerType: \"loop\", event: \"videoEnded\" })\r\n            );\r\n            setTimeout(() => {\r\n              localStorage.removeItem(PLAYER_EVENT_KEY);\r\n            }, 100);\r\n          } else {\r\n            console.log(\"LoopPlayer: Ignoring ENDED state during video loading.\");\r\n          }\r\n          break;\r\n        case YT.PlayerState.PLAYING:\r\n          state = \"playing\";\r\n          isLoadingVideo = false; // Video started playing, loading complete\r\n          break;\r\n        case YT.PlayerState.PAUSED:\r\n          state = \"paused\";\r\n          break;\r\n        case YT.PlayerState.BUFFERING:\r\n          state = \"buffering\";\r\n          break;\r\n        case YT.PlayerState.CUED:\r\n          state = \"cued\";\r\n          break;\r\n        case YT.PlayerState.UNSTARTED:\r\n          state = \"unstarted\";\r\n          break;\r\n        default:\r\n          state = \"unknown\";\r\n      }\r\n      console.log(\"LoopPlayer: State changed to:\", state);\r\n    }\r\n\r\n    // Function to handle player errors\r\n    function onPlayerError(event) {\r\n      let errorMessage = \"Unknown error\";\r\n      switch (event.data) {\r\n        case 2:\r\n          errorMessage = \"Invalid video ID or video not found.\";\r\n          break;\r\n        case 100:\r\n          errorMessage = \"Video not found.\";\r\n          break;\r\n        case 101:\r\n        case 150:\r\n          errorMessage =\r\n            \"Video cannot be played in an embedded player (e.g., private video, restricted playback).\";\r\n          break;\r\n      }\r\n      console.error(\r\n        \"LoopPlayer: Error:\",\r\n        errorMessage,\r\n        \"Error code:\",\r\n        event.data\r\n      );\r\n      // Notify Controller.html that the video failed to load/play\r\n      localStorage.setItem(\r\n        PLAYER_EVENT_KEY,\r\n        JSON.stringify({\r\n          playerType: \"loop\",\r\n          event: \"videoError\",\r\n          errorCode: event.data,\r\n        })\r\n      );\r\n      setTimeout(() => {\r\n        localStorage.removeItem(PLAYER_EVENT_KEY); // Clear the item after a short delay\r\n      }, 100);\r\n    }\r\n    function reportEvent(eventName, data = {}) {\r\n      const eventData = {\r\n        playerType: \"loop\",\r\n        event: eventName,\r\n        timestamp: Date.now(),\r\n        ...data,\r\n      };\r\n      localStorage.setItem(PLAYER_EVENT_KEY, JSON.stringify(eventData));\r\n      // Clear the item after a short delay to ensure the 'storage' event fires cleanly\r\n      setTimeout(() => {\r\n        localStorage.removeItem(PLAYER_EVENT_KEY);\r\n      }, 100);\r\n    }\r\n\r\n    // 24/7 Reliability: Store interval ID for cleanup\r\n    timeUpdateInterval = setInterval(() => {\r\n      // FIX 3: Add a guard clause to ensure the player object exists and is ready\r\n      if (!player || typeof player.getPlayerState !== \"function\") {\r\n        return;\r\n      }\r\n      // Read duration fresh every tick — caching it once made every later\r\n      // video inherit the first video's duration (and remaining time went\r\n      // negative, which the controller renders as a blank).\r\n      const duration = player.getDuration();\r\n      const currentTime = player.getCurrentTime();\r\n      // getDuration() returns 0 until the video's metadata is loaded — skip until then\r\n      if (player.getPlayerState() === YT.PlayerState.PLAYING && duration > 0) {\r\n        reportEvent(\"timeUpdate\", {\r\n          currentTime,\r\n          duration,\r\n          remainingTime: Math.max(0, duration - currentTime)\r\n        });\r\n      }\r\n    }, 1000);\r\n\r\n    // Load the YouTube API when the page loads\r\n    loadYouTubeAPI();\r\n  </script>\r\n</body>\r\n\r\n</html>"},"manifest.json":{"contentType":"application/json; charset=utf-8","binary":false,"content":"{\n  \"name\": \"Live TV Controller\",\n  \"short_name\": \"LiveTV\",\n  \"description\": \"Live TV scheduler, OBS controller, and stream monitor\",\n  \"start_url\": \"/\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#0f172a\",\n  \"theme_color\": \"#0f172a\",\n  \"icons\": [\n    { \"src\": \"/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\" },\n    { \"src\": \"/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\" }\n  ]\n}\n"},"obs-auto-setup.html":{"contentType":"text/html; charset=utf-8","binary":false,"content":"<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>OBS Automation Hub</title>\r\n    <!-- Import OBS WebSocket v5 library -->\r\n    <script src=\"https://cdn.jsdelivr.net/npm/obs-websocket-js@5.0.3/dist/obs-ws.js\"></script>\r\n    <!-- Tailwind CSS for a premium, clean dark interface -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n</head>\r\n<body class=\"bg-zinc-950 text-zinc-100 min-h-screen flex flex-col items-center justify-center p-6\">\r\n\r\n    <div class=\"w-full max-w-lg bg-zinc-900 border border-zinc-800 rounded-2xl p-8 shadow-2xl space-y-6\">\r\n        <!-- Header -->\r\n        <div class=\"text-center space-y-2\">\r\n            <h1 class=\"text-2xl font-bold tracking-tight text-white\">OBS Setup Automation</h1>\r\n            <p class=\"text-sm text-zinc-400\">Configure multi-player layouts, encoder profiles, & RTMP targets on your current profile</p>\r\n        </div>\r\n\r\n        <!-- Connection Status & Inputs -->\r\n        <div class=\"space-y-4\">\r\n            <div class=\"flex items-center justify-between p-4 bg-zinc-950/50 rounded-xl border border-zinc-800\">\r\n                <span class=\"text-sm font-medium text-zinc-400\">Connection Status:</span>\r\n                <span id=\"status\" class=\"inline-flex items-center px-3 py-1 rounded-full text-xs font-semibold bg-amber-500/10 text-amber-500\">\r\n                    Connecting...\r\n                </span>\r\n            </div>\r\n\r\n            <!-- Custom Destination Path Input -->\r\n            <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4\">\r\n                <div class=\"space-y-1\">\r\n                    <label for=\"recordingPath\" class=\"text-xs font-semibold text-zinc-400 uppercase tracking-wider\">Recording Path (Auto-Fetched)</label>\r\n                    <input \r\n                        type=\"text\" \r\n                        id=\"recordingPath\" \r\n                        value=\"\" \r\n                        class=\"w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-indigo-500 text-zinc-300 font-mono\"\r\n                        placeholder=\"Retrieving path from OBS...\"\r\n                    />\r\n                </div>\r\n                <div class=\"space-y-1\">\r\n                    <label for=\"playerPort\" class=\"text-xs font-semibold text-zinc-400 uppercase tracking-wider\">Player Web Port</label>\r\n                    <input \r\n                        type=\"number\" \r\n                        id=\"playerPort\" \r\n                        value=\"3004\" \r\n                        class=\"w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-indigo-500 text-zinc-300 font-mono\"\r\n                        placeholder=\"3004\"\r\n                    />\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Action Button -->\r\n        <button \r\n            id=\"setupBtn\" \r\n            disabled \r\n            class=\"w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-500 disabled:bg-zinc-800 disabled:text-zinc-600 disabled:cursor-not-allowed font-medium text-sm rounded-xl transition-all shadow-lg shadow-indigo-600/10 active:scale-95\"\r\n        >\r\n            Apply Config & Create 4 Sources\r\n        </button>\r\n\r\n        <!-- Log Area -->\r\n        <div class=\"space-y-2\">\r\n            <span class=\"text-xs font-semibold text-zinc-500 uppercase tracking-wider\">Activity Feed</span>\r\n            <div \r\n                id=\"log\" \r\n                class=\"w-full h-48 bg-zinc-950 border border-zinc-800 rounded-xl p-3 text-xs font-mono overflow-y-auto text-zinc-400 space-y-1\"\r\n            >\r\n                <div class=\"text-zinc-500\">&gt; Waiting for connection...</div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <script>\r\n        const obs = new OBSWebSocket();\r\n        const statusEl = document.getElementById('status');\r\n        const setupBtn = document.getElementById('setupBtn');\r\n        const logEl = document.getElementById('log');\r\n        const pathInput = document.getElementById('recordingPath');\r\n        const portInput = document.getElementById('playerPort');\r\n\r\n        function addLog(message, isError = false) {\r\n            const entry = document.createElement('div');\r\n            entry.className = isError ? 'text-rose-500 font-semibold' : 'text-zinc-400';\r\n            entry.innerHTML = `<span class=\"text-zinc-600\">&gt;</span> ${message}`;\r\n            logEl.appendChild(entry);\r\n            logEl.scrollTop = logEl.scrollHeight;\r\n        }\r\n\r\n        // Auto-Connect to local OBS WebSocket instance on port 4455 (No Auth)\r\n        async function connectOBS() {\r\n            try {\r\n                await obs.connect('ws://localhost:4455');\r\n                statusEl.innerText = \"Connected\";\r\n                statusEl.className = \"inline-flex items-center px-3 py-1 rounded-full text-xs font-semibold bg-emerald-500/10 text-emerald-400\";\r\n                setupBtn.disabled = false;\r\n                addLog(\"Successfully linked to OBS WebSocket server on port 4455.\");\r\n\r\n                // Automatically query and set the current active recording directory from OBS\r\n                try {\r\n                    const { recordDirectory } = await obs.call('GetRecordDirectory');\r\n                    if (recordDirectory) {\r\n                        pathInput.value = recordDirectory;\r\n                        addLog(`Retrieved current OBS recording path: \"${recordDirectory}\"`);\r\n                    }\r\n                } catch (pathErr) {\r\n                    addLog(\"Could not auto-fetch recording directory from OBS. Using fallback.\", true);\r\n                    pathInput.value = \"C:/Users/YourUsername/Documents\";\r\n                }\r\n            } catch (error) {\r\n                statusEl.innerText = \"Offline\";\r\n                statusEl.className = \"inline-flex items-center px-3 py-1 rounded-full text-xs font-semibold bg-rose-500/10 text-rose-400\";\r\n                addLog(\"Failed to link with OBS. Verify OBS is running and WebSockets are enabled.\", true);\r\n                console.error(\"OBS Connection Error:\", error);\r\n            }\r\n        }\r\n\r\n        setupBtn.addEventListener('click', async () => {\r\n            setupBtn.disabled = true;\r\n            addLog(\"Executing configuration sequence on current profile...\");\r\n\r\n            try {\r\n                const port = portInput.value || \"3004\";\r\n                const browserSources = [\r\n                    { name: \"Loop Player\", url: `http://localhost:${port}/LoopPlayer.html` },\r\n                    { name: \"Live Player\", url: `http://localhost:${port}/LivePlayer.html` },\r\n                    { name: \"Delay Live\", url: `http://localhost:${port}/DelayLive.html` },\r\n                    { name: \"Local Player\", url: `http://localhost:${port}/LocalPCPlayer.html` }\r\n                ];\r\n\r\n                // Fetch current active profile details\r\n                const { currentProfileName } = await obs.call('GetProfileList');\r\n                addLog(`Modifying profile directly: \"${currentProfileName}\"`);\r\n\r\n                // 1. Set Video Resolution & Framerate (Canvas and Scaled: 1920x1080 @ 50 FPS)\r\n                addLog(\"Applying Video Canvas parameters (1920x1080 @ 50 FPS)...\");\r\n                await obs.call('SetVideoSettings', {\r\n                    fpsNumerator: 50,\r\n                    fpsDenominator: 1,\r\n                    baseWidth: 1920,\r\n                    baseHeight: 1080,\r\n                    outputWidth: 1920,\r\n                    outputHeight: 1080\r\n                });\r\n\r\n                // 2. Global Device Audios: Completely Disable Desktop and Mic Devices\r\n                addLog(\"Disabling all default global audio devices in current profile...\");\r\n                const globalAudioSources = [\r\n                    'DesktopDevice1', 'DesktopDevice2',\r\n                    'AuxDevice1', 'AuxDevice2', 'AuxDevice3', 'AuxDevice4'\r\n                ];\r\n                for (const device of globalAudioSources) {\r\n                    await obs.call('SetProfileParameter', {\r\n                        parameterCategory: 'Audio',\r\n                        parameterName: device,\r\n                        parameterValue: 'Disabled'\r\n                    });\r\n                }\r\n\r\n                // 3. Streaming and Recording Profile Settings -> Switch Output Mode to Advanced\r\n                addLog(\"Setting Output Mode to 'Advanced'...\");\r\n                await obs.call('SetProfileParameter', { parameterCategory: 'Output', parameterName: 'Mode', parameterValue: 'Advanced' });\r\n                \r\n                // Advanced Recording formats\r\n                addLog(\"Setting Recording Directory & file formats (Fragmented MP4)...\");\r\n                await obs.call('SetProfileParameter', { parameterCategory: 'AdvOut', parameterName: 'RecFormat', parameterValue: 'fragmented_mp4' });\r\n                await obs.call('SetRecordDirectory', { recordDirectory: pathInput.value });\r\n\r\n                // 4. Multi-Layer Bitrate Configuration on Current Profile (CBR, 6000 kbps, 2s Keyframes)\r\n                addLog(\"Writing encoder bitrate settings: 6000 kbps (CBR)...\");\r\n                const targetCategories = [\r\n                    'AdvOut', 'SimpleOutput', \r\n                    'AdvX264', 'AdvNVIDIA', 'AdvAMD', 'AdvFFmpeg',\r\n                    'x264', 'jim_nvenc', 'ffmpeg_nvenc', 'amd_amf'\r\n                ];\r\n\r\n                for (const cat of targetCategories) {\r\n                    try {\r\n                        await obs.call('SetProfileParameter', { parameterCategory: cat, parameterName: 'bitrate', parameterValue: '6000' });\r\n                        await obs.call('SetProfileParameter', { parameterCategory: cat, parameterName: 'Bitrate', parameterValue: '6000' });\r\n                        await obs.call('SetProfileParameter', { parameterCategory: cat, parameterName: 'VBitrate', parameterValue: '6000' });\r\n                        \r\n                        await obs.call('SetProfileParameter', { parameterCategory: cat, parameterName: 'rate_control', parameterValue: 'CBR' });\r\n                        await obs.call('SetProfileParameter', { parameterCategory: cat, parameterName: 'RateControl', parameterValue: 'CBR' });\r\n                        \r\n                        await obs.call('SetProfileParameter', { parameterCategory: cat, parameterName: 'keyint_sec', parameterValue: '2' });\r\n                        await obs.call('SetProfileParameter', { parameterCategory: cat, parameterName: 'KeyframeIntervalSec', parameterValue: '2' });\r\n                        await obs.call('SetProfileParameter', { parameterCategory: cat, parameterName: 'keyint', parameterValue: '100' }); \r\n                    } catch (e) {\r\n                        // Safe bypass\r\n                    }\r\n                }\r\n\r\n                // Live Active Encoder Sync (Ensures changes apply instantly to the current session)\r\n                try {\r\n                    addLog(\"Syncing active live encoder configurations...\");\r\n                    const encoderSettingsRes = await obs.call('GetStreamEncoderSettings', { encoderName: 'h264_stream' });\r\n                    if (encoderSettingsRes && encoderSettingsRes.encoderSettings) {\r\n                        const originalSettings = encoderSettingsRes.encoderSettings;\r\n                        const targetSettings = {\r\n                            ...originalSettings,\r\n                            bitrate: 6000,\r\n                            rate_control: \"CBR\",\r\n                            keyint_sec: 2\r\n                        };\r\n                        await obs.call('SetStreamEncoderSettings', {\r\n                            encoderName: 'h264_stream',\r\n                            encoderSettings: targetSettings\r\n                        });\r\n                        addLog(\"✅ Live encoder configuration successfully synced.\");\r\n                    }\r\n                } catch (encError) {\r\n                    console.warn(\"Direct encoder update bypass:\", encError);\r\n                }\r\n\r\n                // 5. Configure custom YouTube RTMP Destination\r\n                addLog(\"Setting target server to YouTube RTMP...\");\r\n                await obs.call('SetStreamServiceSettings', {\r\n                    streamServiceType: 'rtmp_custom',\r\n                    streamServiceSettings: {\r\n                        server: 'rtmp://a.rtmp.youtube.com/live2',\r\n                        key: '' \r\n                    }\r\n                });\r\n\r\n                // 6. Create / Configure the 4 Browser Sources\r\n                addLog(\"Locating active program scene...\");\r\n                const { currentProgramSceneName } = await obs.call('GetCurrentProgramScene');\r\n\r\n                const { sceneItems } = await obs.call('GetSceneItemList', { sceneName: currentProgramSceneName });\r\n\r\n                for (const item of browserSources) {\r\n                    const existingItem = sceneItems.find(s => s.sourceName === item.name);\r\n                    let targetItemId;\r\n\r\n                    if (!existingItem) {\r\n                        addLog(`Creating Browser Source: \"${item.name}\"...`);\r\n                        const sourceRes = await obs.call('CreateInput', {\r\n                            sceneName: currentProgramSceneName,\r\n                            inputName: item.name,\r\n                            inputKind: 'browser_source',\r\n                            inputSettings: {\r\n                                url: item.url,\r\n                                width: 1920,\r\n                                height: 1080,\r\n                                reroute_audio: true // Control audio via OBS\r\n                            }\r\n                        });\r\n                        targetItemId = sourceRes.sceneItemId;\r\n                    } else {\r\n                        addLog(`\"${item.name}\" already exists on scene. Re-using target ID.`);\r\n                        targetItemId = existingItem.sceneItemId;\r\n                    }\r\n\r\n                    // Lock Transform\r\n                    addLog(`Locking transform layout for \"${item.name}\"...`);\r\n                    await obs.call('SetSceneItemLocked', {\r\n                        sceneName: currentProgramSceneName,\r\n                        sceneItemId: targetItemId,\r\n                        sceneItemLocked: true\r\n                    });\r\n\r\n                    // AUDIO MONITORING POLLING RETRY LOOP FOR EACH SOURCE\r\n                    addLog(`Awaiting initialization of Browser Audio Node for \"${item.name}\"...`);\r\n                    let monitorSuccess = false;\r\n                    for (let attempt = 1; attempt <= 12; attempt++) {\r\n                        try {\r\n                            await obs.call('SetInputAudioMonitorType', {\r\n                                inputName: item.name,\r\n                                monitorType: 'OBS_MONITORING_TYPE_MONITOR_AND_OUTPUT'\r\n                            });\r\n                            monitorSuccess = true;\r\n                            addLog(`✅ Audio for \"${item.name}\" set to: 'Monitor and Output'.`);\r\n                            break;\r\n                        } catch (audioErr) {\r\n                            // Source audio node is still booting up; wait and try again\r\n                            await new Promise(resolve => setTimeout(resolve, 250));\r\n                        }\r\n                    }\r\n                    if (!monitorSuccess) {\r\n                        addLog(`⚠️ Audio monitor settings did not apply instantly to \"${item.name}\". Please double check Audio settings in OBS.`, true);\r\n                    }\r\n                }\r\n\r\n                // 7. Complete System Audio Muting Guardrail\r\n                addLog(\"Running absolute mute routine for all default Desktop and Mic audio devices...\");\r\n                try {\r\n                    const { inputs } = await obs.call('GetInputList');\r\n                    const protectedSources = browserSources.map(s => s.name);\r\n                    for (const input of inputs) {\r\n                        const inputName = input.inputName.toLowerCase();\r\n                        if (inputName.includes('desktop') || inputName.includes('mic') || inputName.includes('aux')) {\r\n                            if (!protectedSources.includes(input.inputName)) {\r\n                                await obs.call('SetInputMute', { inputName: input.inputName, inputMuted: true });\r\n                                addLog(`Muted active global input: \"${input.inputName}\"`);\r\n                            }\r\n                        }\r\n                    }\r\n                } catch (muteError) {\r\n                    console.warn(muteError);\r\n                }\r\n\r\n                addLog(\"✅ Configuration complete! All settings have been applied directly to your active profile.\");\r\n\r\n            } catch (error) {\r\n                console.error(\"Configuration Error:\", error);\r\n                addLog(`Setup failed: ${error.message || error}`, true);\r\n            } finally {\r\n                setupBtn.disabled = false;\r\n            }\r\n        });\r\n\r\n        // Initialize connection\r\n        connectOBS();\r\n    </script>\r\n</body>\r\n</html>"},"setup.html":{"contentType":"text/html; charset=utf-8","binary":false,"content":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0\" />\n  <title>Live TV — Enable Notifications</title>\n  <style>\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    body {\n      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;\n      background: #0f172a;\n      color: #e2e8f0;\n      min-height: 100vh;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      padding: 24px;\n    }\n\n    .card {\n      background: #1e293b;\n      border: 1px solid #334155;\n      border-radius: 16px;\n      padding: 36px 28px;\n      max-width: 420px;\n      width: 100%;\n      text-align: center;\n    }\n\n    .icon { font-size: 48px; margin-bottom: 16px; }\n\n    h1 {\n      font-size: 22px;\n      font-weight: 700;\n      color: #f1f5f9;\n      margin-bottom: 8px;\n    }\n\n    .subtitle {\n      font-size: 14px;\n      color: #94a3b8;\n      margin-bottom: 28px;\n      line-height: 1.6;\n    }\n\n    .btn {\n      display: block;\n      width: 100%;\n      padding: 14px 20px;\n      border-radius: 10px;\n      border: none;\n      font-size: 16px;\n      font-weight: 600;\n      cursor: pointer;\n      transition: opacity 0.15s, transform 0.1s;\n    }\n    .btn:active { transform: scale(0.98); }\n    .btn:disabled { opacity: 0.5; cursor: not-allowed; }\n\n    .btn-primary { background: #06b6d4; color: #0f172a; }\n    .btn-primary:hover:not(:disabled) { opacity: 0.9; }\n\n    .btn-secondary {\n      background: #334155;\n      color: #e2e8f0;\n      margin-top: 10px;\n      font-size: 14px;\n      padding: 10px 16px;\n    }\n\n    .status {\n      margin-top: 20px;\n      padding: 14px;\n      border-radius: 10px;\n      font-size: 14px;\n      line-height: 1.5;\n      display: none;\n      text-align: left;\n    }\n    .status.show { display: block; }\n    .status.success { background: #14532d; border: 1px solid #16a34a; color: #86efac; }\n    .status.error   { background: #450a0a; border: 1px solid #dc2626; color: #fca5a5; }\n    .status.info    { background: #1e3a5f; border: 1px solid #3b82f6; color: #93c5fd; }\n    .status.warn    { background: #431407; border: 1px solid #ea580c; color: #fdba74; }\n\n    .spinner {\n      display: inline-block;\n      width: 18px; height: 18px;\n      border: 2px solid #0f172a40;\n      border-top-color: #0f172a;\n      border-radius: 50%;\n      animation: spin 0.7s linear infinite;\n      vertical-align: middle;\n      margin-right: 8px;\n    }\n    @keyframes spin { to { transform: rotate(360deg); } }\n\n    .features {\n      text-align: left;\n      margin-bottom: 28px;\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n    }\n    .feature {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      font-size: 14px;\n      color: #cbd5e1;\n    }\n    .feature-icon { font-size: 18px; flex-shrink: 0; }\n\n    .diag {\n      margin-top: 20px;\n      background: #0f172a;\n      border: 1px solid #334155;\n      border-radius: 8px;\n      padding: 12px;\n      font-size: 12px;\n      color: #64748b;\n      text-align: left;\n    }\n    .diag-row { display: flex; justify-content: space-between; margin-bottom: 4px; }\n    .diag-ok   { color: #4ade80; }\n    .diag-fail { color: #f87171; }\n    .diag-warn { color: #fb923c; }\n  </style>\n</head>\n<body>\n<div class=\"card\">\n  <div class=\"icon\">📺</div>\n  <h1>Live TV Controller</h1>\n  <p class=\"subtitle\">Enable push notifications to get alerts on this phone — even on 4G/5G after setup.</p>\n\n  <div class=\"features\">\n    <div class=\"feature\"><span class=\"feature-icon\">🗓️</span> Schedule triggered alerts</div>\n    <div class=\"feature\"><span class=\"feature-icon\">🔴</span> Recording started / stopped</div>\n    <div class=\"feature\"><span class=\"feature-icon\">📡</span> Live stream detected</div>\n    <div class=\"feature\"><span class=\"feature-icon\">⚠️</span> System warnings</div>\n  </div>\n\n  <button class=\"btn btn-primary\" id=\"btn\" onclick=\"setup()\">\n    🔔 Enable Notifications\n  </button>\n  <button class=\"btn btn-secondary\" id=\"btn-test\" onclick=\"sendTestNow()\" style=\"display:none\">\n    🧪 Send test notification\n  </button>\n\n  <div class=\"status\" id=\"status\"></div>\n\n  <div class=\"diag\" id=\"diag\" style=\"display:none\">\n    <div class=\"diag-row\"><span>Push support</span><span id=\"d-push\">checking…</span></div>\n    <div class=\"diag-row\"><span>Notification permission</span><span id=\"d-perm\">checking…</span></div>\n    <div class=\"diag-row\"><span>Service worker</span><span id=\"d-sw\">checking…</span></div>\n    <div class=\"diag-row\"><span>FCM token</span><span id=\"d-token\">checking…</span></div>\n    <div class=\"diag-row\"><span>Server status</span><span id=\"d-server\">checking…</span></div>\n  </div>\n</div>\n\n<script type=\"module\">\n  import { initializeApp }  from 'https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js';\n  import { getMessaging, getToken, onMessage, deleteToken } from 'https://www.gstatic.com/firebasejs/10.12.0/firebase-messaging.js';\n\n  const FIREBASE_CONFIG = {\n    apiKey:            'AIzaSyArEsWAGlOF2VPZVb9lPYEGesgDAAE6RYE',\n    authDomain:        'live-tv-1dab0.firebaseapp.com',\n    projectId:         'live-tv-1dab0',\n    storageBucket:     'live-tv-1dab0.firebasestorage.app',\n    messagingSenderId: '221221340671',\n    appId:             '1:221221340671:web:986f566248262a4d1093ca',\n  };\n  const VAPID_KEY = 'BAW5sxTZ-NUY6-nurk5LPrg3s_TaKf3sDNl0LRWXjbxYfWqtiJox8E5UqkuEZaO0exz5_b4K-_t84x2PVOHBccM';\n\n  const btn      = document.getElementById('btn');\n  const btnTest  = document.getElementById('btn-test');\n  const statusEl = document.getElementById('status');\n  const diagEl   = document.getElementById('diag');\n\n  function showStatus(type, msg) {\n    statusEl.className = `status show ${type}`;\n    statusEl.innerHTML = msg;\n  }\n  function d(id, val, cls) {\n    const el = document.getElementById(id);\n    if (el) { el.textContent = val; el.className = cls || ''; }\n  }\n\n  function getBrowserName() {\n    const ua = navigator.userAgent;\n    if (/android/i.test(ua)) return 'Android';\n    if (/iphone|ipad/i.test(ua)) return 'iPhone/iPad';\n    if (ua.includes('Edg/')) return 'Edge';\n    if (ua.includes('Chrome/')) return 'Chrome';\n    if (ua.includes('Firefox/')) return 'Firefox';\n    if (ua.includes('Safari/')) return 'Safari';\n    return 'Browser';\n  }\n\n  // Run diagnostics on page load\n  async function runDiag() {\n    diagEl.style.display = 'block';\n\n    // Push API\n    const hasPush = 'PushManager' in window && 'Notification' in window && 'serviceWorker' in navigator;\n    d('d-push', hasPush ? '✓ supported' : '✗ NOT supported', hasPush ? 'diag-ok' : 'diag-fail');\n    if (!hasPush) {\n      btn.disabled = true;\n      showStatus('error', '❌ This browser does not support push notifications. Use Chrome on Android.');\n      return;\n    }\n\n    // Notification permission\n    const perm = Notification.permission;\n    if (perm === 'granted')  d('d-perm', '✓ granted',  'diag-ok');\n    if (perm === 'denied')   d('d-perm', '✗ BLOCKED — go to Android Settings → Apps → Chrome → Notifications → ON, then clear site permissions', 'diag-fail');\n    if (perm === 'default')  d('d-perm', '⚠ not yet asked', 'diag-warn');\n\n    // Service worker\n    try {\n      const reg = await navigator.serviceWorker.getRegistration('/');\n      if (reg) {\n        d('d-sw', '✓ registered', 'diag-ok');\n      } else {\n        d('d-sw', '⚠ not yet registered', 'diag-warn');\n      }\n    } catch (e) {\n      d('d-sw', '✗ error: ' + e.message, 'diag-fail');\n    }\n\n    // FCM token\n    const saved = localStorage.getItem('fcm_token');\n    d('d-token', saved ? '✓ saved (' + saved.slice(0, 12) + '…)' : '⚠ none', saved ? 'diag-ok' : 'diag-warn');\n\n    // Server notification status\n    try {\n      const r = await fetch('/api/notifications/status');\n      const s = await r.json();\n      if (s.ready) {\n        d('d-server', `✓ ready (${s.activeDevices} device${s.activeDevices !== 1 ? 's' : ''})`, 'diag-ok');\n      } else {\n        d('d-server', '✗ NOT ready — restart the server', 'diag-fail');\n      }\n    } catch {\n      d('d-server', '✗ server not reachable', 'diag-fail');\n    }\n\n    // Show test button if already registered\n    if (perm === 'granted' && saved) {\n      btnTest.style.display = 'block';\n      btn.textContent = '🔄 Re-register this device';\n    }\n  }\n\n  runDiag();\n\n  // Foreground message handler — shows notification when this tab is in focus\n  let messagingInstance = null;\n  async function initForegroundHandler(swReg) {\n    try {\n      const app       = initializeApp(FIREBASE_CONFIG);\n      messagingInstance = getMessaging(app);\n      onMessage(messagingInstance, (payload) => {\n        navigator.serviceWorker.ready.then((reg) => {\n          const n = payload.notification || {};\n          const tag = payload.data?.tag || 'livetv';\n          reg.showNotification(n.title || 'Live TV Controller', {\n            body: n.body || '', icon: n.icon || '/icon-192.png',\n            tag, renotify: true, badge: '/icon-192.png',\n          });\n        });\n      });\n    } catch (_) {}\n  }\n\n  // Try to set up foreground handler on page load if already registered\n  navigator.serviceWorker.getRegistration('/').then(reg => {\n    if (reg) initForegroundHandler(reg);\n  }).catch(() => {});\n\n  // Send a test notification via the server\n  window.sendTestNow = async function () {\n    btnTest.disabled = true;\n    btnTest.innerHTML = '<span class=\"spinner\"></span>Sending…';\n    try {\n      const r = await fetch('/api/notifications/test', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ token: localStorage.getItem('fcm_token') }),\n      });\n      if (r.ok) {\n        showStatus('success', '✅ Test sent! Check your notification shade.\\n\\nIf you see nothing:\\n• Android Settings → Apps → Chrome → Notifications must be ON\\n• Chrome → Site Settings → Notifications → this site must be Allowed');\n      } else {\n        const e = await r.json();\n        showStatus('error', '❌ Server error: ' + (e.error || r.status));\n      }\n    } catch (err) {\n      showStatus('error', '❌ ' + err.message);\n    }\n    btnTest.disabled = false;\n    btnTest.innerHTML = '🧪 Send test notification';\n  };\n\n  window.setup = async function() {\n    btn.disabled = true;\n    btn.innerHTML = '<span class=\"spinner\"></span>Step 1/4: Registering service worker…';\n    showStatus('info', 'Setting up…');\n\n    try {\n      // Step 1: Register service worker (force update to get fresh SW)\n      const swReg = await navigator.serviceWorker.register('/firebase-messaging-sw.js', {\n        scope: '/',\n        updateViaCache: 'none',  // always fetch fresh SW script\n      });\n      // Wait for SW to be active\n      await new Promise(resolve => {\n        if (swReg.active) { resolve(); return; }\n        const sw = swReg.installing || swReg.waiting;\n        if (sw) sw.addEventListener('statechange', () => { if (sw.state === 'activated') resolve(); });\n        else resolve();\n      });\n      d('d-sw', '✓ registered', 'diag-ok');\n\n      // Step 2: Request notification permission\n      btn.innerHTML = '<span class=\"spinner\"></span>Step 2/4: Requesting permission…';\n      const permission = await Notification.requestPermission();\n      localStorage.setItem('fcm_permission_status', permission);\n      d('d-perm', permission === 'granted' ? '✓ granted' : '✗ ' + permission,\n        permission === 'granted' ? 'diag-ok' : 'diag-fail');\n\n      if (permission !== 'granted') {\n        showStatus('error',\n          '❌ Permission denied.<br><br>' +\n          '<b>On Android:</b><br>' +\n          '1. Android Settings → Apps → Chrome → Notifications → turn ON<br>' +\n          '2. Come back here and tap Enable again');\n        btn.innerHTML = '🔔 Enable Notifications';\n        btn.disabled = false;\n        return;\n      }\n\n      // Step 3: Get FCM token\n      btn.innerHTML = '<span class=\"spinner\"></span>Step 3/4: Getting device token…';\n      showStatus('info', 'Connecting to Firebase…');\n\n      const app       = initializeApp(FIREBASE_CONFIG);\n      messagingInstance = getMessaging(app);\n\n      // Read OLD token BEFORE overwriting (needed for cleanup)\n      const oldToken = localStorage.getItem('fcm_token');\n\n      let token = null;\n      for (let i = 1; i <= 3; i++) {\n        try {\n          token = await getToken(messagingInstance, { vapidKey: VAPID_KEY, serviceWorkerRegistration: swReg });\n          break;\n        } catch (e) {\n          if (i === 3) throw new Error('Could not get FCM token: ' + e.message);\n          await new Promise(r => setTimeout(r, i * 1500));\n        }\n      }\n\n      if (!token) throw new Error('FCM returned empty token');\n      d('d-token', '✓ ' + token.slice(0, 12) + '…', 'diag-ok');\n\n      // Step 4: Register with server (remove old token first to prevent duplicates)\n      btn.innerHTML = '<span class=\"spinner\"></span>Step 4/4: Registering with server…';\n\n      if (oldToken && oldToken !== token) {\n        // Delete old token from server so only 1 token per device\n        try {\n          await fetch('/api/notifications/register', {\n            method: 'DELETE',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ token: oldToken }),\n          });\n        } catch (_) { /* best effort */ }\n      }\n\n      // Save new token\n      localStorage.setItem('fcm_token', token);\n\n      const res = await fetch('/api/notifications/register', {\n        method:  'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          token,\n          deviceName: `${getBrowserName()} on ${navigator.platform || 'Device'}`,\n          userAgent:  navigator.userAgent,\n        }),\n      });\n\n      if (!res.ok) throw new Error(`Server error: ${res.status}`);\n\n      // Set up foreground handler so notifications show when this tab is open\n      onMessage(messagingInstance, (payload) => {\n        navigator.serviceWorker.ready.then((reg) => {\n          const n = payload.notification || {};\n          const tag = payload.data?.tag || 'livetv';\n          reg.showNotification(n.title || 'Live TV Controller', {\n            body: n.body || '', icon: n.icon || '/icon-192.png',\n            tag, renotify: true, badge: '/icon-192.png',\n          });\n        });\n      });\n\n      // Re-check server status\n      try {\n        const sr = await fetch('/api/notifications/status');\n        const ss = await sr.json();\n        d('d-server', ss.ready\n          ? `✓ ready (${ss.activeDevices} device${ss.activeDevices !== 1 ? 's' : ''})`\n          : '✗ NOT ready — restart server', ss.ready ? 'diag-ok' : 'diag-fail');\n      } catch (_) {}\n\n      showStatus('success',\n        '✅ Done! Notifications enabled.<br><br>' +\n        'Tap <b>Send test notification</b> below to verify your phone shows it.<br><br>' +\n        '<span style=\"font-size:12px;opacity:0.8\">If the test arrives but you still miss real notifications:<br>' +\n        '• Android Settings → Apps → Chrome → Notifications → ON<br>' +\n        '• Keep Chrome running in the background</span>');\n\n      btn.innerHTML = '🔄 Re-register this device';\n      btn.disabled = false;\n      btnTest.style.display = 'block';\n\n    } catch (err) {\n      console.error('[Setup]', err);\n      showStatus('error', `❌ Setup failed: ${err.message}`);\n      btn.innerHTML = '🔔 Try Again';\n      btn.disabled = false;\n    }\n  };\n</script>\n</body>\n</html>\n"},"vite.svg":{"contentType":"image/svg+xml","binary":false,"content":"<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" aria-hidden=\"true\" role=\"img\" class=\"iconify iconify--logos\" width=\"31.88\" height=\"32\" preserveAspectRatio=\"xMidYMid meet\" viewBox=\"0 0 256 257\"><defs><linearGradient id=\"IconifyId1813088fe1fbc01fb466\" x1=\"-.828%\" x2=\"57.636%\" y1=\"7.652%\" y2=\"78.411%\"><stop offset=\"0%\" stop-color=\"#41D1FF\"></stop><stop offset=\"100%\" stop-color=\"#BD34FE\"></stop></linearGradient><linearGradient id=\"IconifyId1813088fe1fbc01fb467\" x1=\"43.376%\" x2=\"50.316%\" y1=\"2.242%\" y2=\"89.03%\"><stop offset=\"0%\" stop-color=\"#FFEA83\"></stop><stop offset=\"8.333%\" stop-color=\"#FFDD35\"></stop><stop offset=\"100%\" stop-color=\"#FFA800\"></stop></linearGradient></defs><path fill=\"url(#IconifyId1813088fe1fbc01fb466)\" d=\"M255.153 37.938L134.897 252.976c-2.483 4.44-8.862 4.466-11.382.048L.875 37.958c-2.746-4.814 1.371-10.646 6.827-9.67l120.385 21.517a6.537 6.537 0 0 0 2.322-.004l117.867-21.483c5.438-.991 9.574 4.796 6.877 9.62Z\"></path><path fill=\"url(#IconifyId1813088fe1fbc01fb467)\" d=\"M185.432.063L96.44 17.501a3.268 3.268 0 0 0-2.634 3.014l-5.474 92.456a3.268 3.268 0 0 0 3.997 3.378l24.777-5.718c2.318-.535 4.413 1.507 3.936 3.838l-7.361 36.047c-.495 2.426 1.782 4.5 4.151 3.78l15.304-4.649c2.372-.72 4.652 1.36 4.15 3.788l-11.698 56.621c-.732 3.542 3.979 5.473 5.943 2.437l1.313-2.028l72.516-144.72c1.215-2.423-.88-5.186-3.54-4.672l-25.505 4.922c-2.396.462-4.435-1.77-3.759-4.114l16.646-57.705c.677-2.35-1.37-4.583-3.769-4.113Z\"></path></svg>"}};
